(2, 'https://prephq.theiotacademy.co/project/author/prephq/', '54:2ed1ac56f35f5ffab38013d650994124', 1, 'user', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, NULL, 'https://secure.gravatar.com/avatar/30bd7543af7bc09ff1efe2e9b19aec5648e208ba9965d3b0b73bcc607ce0dbef?s=500&d=mm&r=g', NULL, NULL, 'gravatar-image', NULL, NULL, 'https://secure.gravatar.com/avatar/30bd7543af7bc09ff1efe2e9b19aec5648e208ba9965d3b0b73bcc607ce0dbef?s=500&d=mm&r=g', NULL, 'gravatar-image', NULL, NULL, NULL, NULL, '2025-09-15 07:13:41', '2026-03-18 07:46:26', 1, NULL, NULL, NULL, NULL, 0, NULL, 2, '2026-03-18 07:46:26', '2025-09-05 09:49:37', NULL),
