(4, 'https://prephq.theiotacademy.co/project/embedded-systems-projects-for-ece/', '74:856caf8f4733c1f4ea0da8a901a2cb00', 10, 'post', 'post', 1, 0, 'Embedded Systems Projects for ECE That Inspire Innovation', 'Dive into embedded systems projects for ECE. This guide offers project ideas and tips for mastering essential hardware and software skills.', 'Embedded Systems Projects for ECE: Mini, Major &amp; Final Year Ideas', 'publish', NULL, 0, NULL, NULL, NULL, 'embedded systems projects for ECE', 82, 60, 0, NULL, 0, NULL, NULL, NULL, NULL, 'https://prephq.theiotacademy.co/project/wp-content/uploads/2025/09/7-Embedded-Systems-Projects-for-ECE-01.webp', NULL, '12', 'featured-image', NULL, NULL, 'https://prephq.theiotacademy.co/project/wp-content/uploads/2025/09/7-Embedded-Systems-Projects-for-ECE-01.webp', '12', 'featured-image', '{\"width\":738,\"height\":423,\"filesize\":113816,\"url\":\"https://prephq.theiotacademy.co/project/wp-content/uploads/2025/09/7-Embedded-Systems-Projects-for-ECE-01.webp\",\"path\":\"/home/u733794648/domains/theiotacademy.co/public_html/prephq/project/wp-content/uploads/2025/09/7-Embedded-Systems-Projects-for-ECE-01.webp\",\"size\":\"full\",\"id\":12,\"alt\":\"Embedded-Systems-Projects-for-ECE\",\"pixels\":312174,\"type\":\"image/webp\"}', 0, NULL, NULL, '2025-09-15 07:14:51', '2025-09-15 09:37:22', 1, NULL, NULL, NULL, NULL, 0, 12, 2, '2025-09-15 09:37:22', '2025-09-15 07:17:08', 0),
